INSERT OR IGNORE INTO [ec_faq] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[question],[answer],[sort_order]) VALUES ('01KQJ350HGFVSCGTZFGHJ3ZD0K','how-do-i-know-if-i-need-hearing-aid','published',NULL,NULL,'2026-05-01T15:40:08.624Z','2026-05-01T15:40:08.625Z','2026-05-01T15:40:08.624Z',NULL,NULL,1,'01KQJ350HH5MP01DAHDHVPMBX0',NULL,'en','01KQJ350HGFVSCGTZFGHJ3ZD0K','How do I know if I need a hearing aid?','If you frequently ask people to repeat themselves, have difficulty hearing in noisy environments, or find yourself turning up the TV volume, it may be time for a hearing evaluation. Schedule an appointment with our audiologist for a comprehensive assessment.','1');
INSERT OR IGNORE INTO [ec_faq] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[question],[answer],[sort_order]) VALUES ('01KQJ350SGN0CFQT32TY919VB0','are-hearing-aids-covered-by-insurance','published',NULL,NULL,'2026-05-01T15:40:08.880Z','2026-05-01T15:40:08.881Z','2026-05-01T15:40:08.880Z',NULL,NULL,1,'01KQJ350SJ0RYC6J10BVY1N9F8',NULL,'en','01KQJ350SGN0CFQT32TY919VB0','Are hearing aids covered by insurance?','Coverage varies by insurance plan. Many plans offer partial coverage for hearing aids. Our team can help you understand your benefits and explore financing options to make hearing care accessible for you.','2');
INSERT OR IGNORE INTO [ec_faq] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[question],[answer],[sort_order]) VALUES ('01KQJ350V7TTJK0FDBNMKDC3X9','how-often-should-i-get-hearing-test','published',NULL,NULL,'2026-05-01T15:40:08.935Z','2026-05-01T15:40:08.939Z','2026-05-01T15:40:08.935Z',NULL,NULL,1,'01KQJ350VBGH6BJV5W9AHPGRJP',NULL,'en','01KQJ350V7TTJK0FDBNMKDC3X9','How often should I get a hearing test?','Adults should have their hearing tested every 3-5 years, or more frequently if you notice changes. Those with existing hearing loss or high noise exposure should be tested annually.','3');
INSERT OR IGNORE INTO [ec_faq] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[question],[answer],[sort_order]) VALUES ('01KQJ350VE5HBKRJVX0X3M5CRD','can-i-get-hearing-aid-without-fitting','published',NULL,NULL,'2026-05-01T15:40:08.943Z','2026-05-01T15:40:08.944Z','2026-05-01T15:40:08.942Z',NULL,NULL,1,'01KQJ350VG8BTC6AY0XFQKSWFV',NULL,'en','01KQJ350VE5HBKRJVX0X3M5CRD','Can I get a hearing aid without a fitting?','A professional fitting is essential for optimal hearing aid performance. Proper fitting ensures the device is programmed correctly for your specific hearing loss, fits comfortably, and delivers the best possible sound quality.','4');
INSERT OR IGNORE INTO [ec_faq] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[question],[answer],[sort_order]) VALUES ('01KQJ350VMXP8HWAXRKNVGP06N','how-can-hearing-aids-help-with-tinnitus','published',NULL,NULL,'2026-05-01T15:40:08.949Z','2026-05-01T15:40:08.952Z','2026-05-01T15:40:08.948Z',NULL,NULL,1,'01KQJ350VRJH9CR0ENPSWZYBBH',NULL,'en','01KQJ350VMXP8HWAXRKNVGP06N','How can hearing aids help with tinnitus?','Many modern hearing aids include tinnitus masking features that produce soothing sounds to reduce the perception of ringing. Combined with hearing amplification, they can significantly improve quality of life for tinnitus sufferers.','5');
